import base64
import json
import os
from typing import Any, Dict, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def decrypt_ciphertext_payload(
    ciphertext_payload: Union[str, bytes, Dict[str, Any]],
    key_id: str | None = None,
    region_name: str | None = None,
) -> bytes:
    """
    Decrypt a ciphertext payload using AWS KMS.

    Supported input formats:
      - base64-encoded ciphertext string
      - raw bytes ciphertext
      - JSON object/dict with keys like:
          * CiphertextBlob / ciphertext_blob / ciphertext
          * EncryptionAlgorithm (optional)
          * KeyId (optional, not required for decrypt)

    Returns:
      Decrypted plaintext bytes.
    """
    kms_client = boto3.client("kms", region_name=region_name)

    encryption_algorithm = None
    ciphertext_blob = None

    if isinstance(ciphertext_payload, dict):
        ciphertext_blob = (
            ciphertext_payload.get("CiphertextBlob")
            or ciphertext_payload.get("ciphertext_blob")
            or ciphertext_payload.get("ciphertext")
        )
        encryption_algorithm = (
            ciphertext_payload.get("EncryptionAlgorithm")
            or ciphertext_payload.get("encryption_algorithm")
        )
        if key_id is None:
            key_id = ciphertext_payload.get("KeyId") or ciphertext_payload.get("key_id")
    elif isinstance(ciphertext_payload, str):
        try:
            parsed = json.loads(ciphertext_payload)
            return decrypt_ciphertext_payload(parsed, key_id=key_id, region_name=region_name)
        except json.JSONDecodeError:
            ciphertext_blob = base64.b64decode(ciphertext_payload)
    elif isinstance(ciphertext_payload, (bytes, bytearray)):
        ciphertext_blob = bytes(ciphertext_payload)
    else:
        raise TypeError("ciphertext_payload must be a str, bytes, or dict")

    if ciphertext_blob is None:
        raise ValueError("Ciphertext payload did not contain a ciphertext blob")

    decrypt_kwargs: Dict[str, Any] = {"CiphertextBlob": ciphertext_blob}
    if key_id:
        decrypt_kwargs["KeyId"] = key_id
    if encryption_algorithm:
        decrypt_kwargs["EncryptionAlgorithm"] = encryption_algorithm

    try:
        response = kms_client.decrypt(**decrypt_kwargs)
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"AWS KMS decrypt failed: {exc}") from exc

    plaintext = response.get("Plaintext")
    if plaintext is None:
        raise RuntimeError("AWS KMS decrypt succeeded but no plaintext was returned")
    return plaintext


def decrypt_ciphertext_payload_text(
    ciphertext_payload: Union[str, bytes, Dict[str, Any]],
    key_id: str | None = None,
    region_name: str | None = None,
    encoding: str = "utf-8",
) -> str:
    return decrypt_ciphertext_payload(ciphertext_payload, key_id=key_id, region_name=region_name).decode(encoding)


if __name__ == "__main__":
    payload = os.environ.get("CIPHERTEXT_PAYLOAD", "")
    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    key_id = os.environ.get("KMS_KEY_ID")
    if payload:
        print(decrypt_ciphertext_payload_text(payload, key_id=key_id, region_name=region))
